# PY-161..PY-230: Lists, Tuples & Sets (25 list, 15 tuple, 20 set, 10 mixed).
D = "Lists, Tuples & Sets"
NL = lambda a, b, lo=4, hi=10: (lambda r: (lambda k: rows(k, " ".join(str(r.randint(a, b)) for _ in range(k))))(r.randint(lo, hi)))
IN = "First line `n`, then one line with `n` integers."

# ---- 25 lists ----
py(D, "Top Three Scores", "A quiz app shows the three highest scores of the day, largest first. Given `n` scores print the top three (or fewer if `n` is smaller).", IN, "The top scores separated by spaces.", "1 <= n <= 100",
   "n = int(input())\nv = sorted(map(int, input().split()), reverse=True)\nprint(*v[:3])", NL(0, 100), edges=["1\n5\n", "2\n3 9\n"])
py(D, "Rotate the Roster", "A duty roster of `n` names rotates left by `k` places each week. Print the roster after the rotation.", "First line `n k`, then `n` names.", "The rotated names.", "1 <= n <= 50, 0 <= k <= 1000",
   "n, k = map(int, input().split())\nnames = input().split()\nk %= n\nprint(*(names[k:] + names[:k]))", lambda r: (lambda n: rows(f"{n} {r.randint(0, 20)}", " ".join(r.sample(["Asha", "Ravi", "Meena", "Kiran", "Sita", "Arun", "Divya", "Naveen", "Tara", "Om"], n))))(r.randint(2, 8)), edges=["1 5\nAsha\n"])
py(D, "Remove Duplicate Orders", "An e-commerce export lists order ids with repeats. Print the ids in first-seen order with duplicates removed.", IN, "The unique ids in original order.", "1 <= n <= 100",
   "n = int(input())\nseen = []\nfor v in input().split():\n    if v not in seen:\n        seen.append(v)\nprint(*seen)", NL(1, 8, 5, 14), edges=["1\n7\n"])
py(D, "Second Highest Bid", "An auction wants the second-highest distinct bid. Print it, or `None` if there is no second distinct bid.", IN, "The second largest distinct value or `None`.", "1 <= n <= 100",
   "n = int(input())\nv = sorted(set(map(int, input().split())), reverse=True)\nprint(v[1] if len(v) > 1 else \"None\")", NL(1, 30, 1, 8), edges=["3\n5 5 5\n", "2\n1 9\n"])
py(D, "Merge Two Class Lists", "Two sections have sorted roll numbers. Merge them into one sorted list without using `sort` on the whole list (use two pointers) and print it.", "Line 1: `n` and its `n` sorted integers; line 2: `m` and its `m` sorted integers.", "The merged list.", "0 <= n, m <= 50",
   "a = input().split()[1:]\nb = input().split()[1:]\na = list(map(int, a))\nb = list(map(int, b))\ni = j = 0\nout = []\nwhile i < len(a) and j < len(b):\n    if a[i] <= b[j]:\n        out.append(a[i])\n        i += 1\n    else:\n        out.append(b[j])\n        j += 1\nout += a[i:] + b[j:]\nprint(*out)",
   lambda r: (lambda a, b: rows(" ".join(map(str, [len(a)] + a)), " ".join(map(str, [len(b)] + b))))(sorted(r.sample(range(1, 60), r.randint(1, 6))), sorted(r.sample(range(1, 60), r.randint(1, 6)))), edges=["0\n2 4 6\n"])
py(D, "Prefix Totals of Sales", "A manager wants cumulative sales: element `i` of the result is the sum of the first `i + 1` days. Print them separated by spaces.", IN, "The cumulative sums.", "1 <= n <= 100",
   "n = int(input())\nout = []\ntotal = 0\nfor v in map(int, input().split()):\n    total += v\n    out.append(total)\nprint(*out)", NL(1, 500), edges=["1\n9\n"])
py(D, "Rainfall Peaks", "A weather station finds days that are strictly higher than both neighbours. Print the 0-based indices of such peaks, or `None`.", IN, "The indices or `None`.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nres = [i for i in range(1, n - 1) if v[i] > v[i - 1] and v[i] > v[i + 1]]\nprint(*res if res else [\"None\"])", NL(0, 20, 3, 12), edges=["1\n5\n", "3\n1 3 1\n"])
py(D, "Insert in Sorted Shelf", "Books are on a shelf by increasing id. Insert a new id `x` so the shelf stays sorted and print the shelf.", "First line `n x`, then `n` sorted integers.", "The shelf after insertion.", "0 <= n <= 100",
   "n, x = map(int, input().split())\nshelf = list(map(int, input().split()))\npos = 0\nwhile pos < len(shelf) and shelf[pos] < x:\n    pos += 1\nshelf.insert(pos, x)\nprint(*shelf)", lambda r: (lambda a: rows(f"{len(a)} {r.randint(0, 60)}", " ".join(map(str, a))))(sorted(r.sample(range(1, 60), r.randint(1, 7)))), edges=["0 5\n\n"])
py(D, "Slice the Playlist", "A playlist of `n` songs shows every second song starting from the first, then the last three songs. Print the two groups on two lines.", "First line `n`, then `n` song ids.", "Two lines of ids.", "3 <= n <= 100",
   "n = int(input())\nsongs = input().split()\nprint(*songs[::2])\nprint(*songs[-3:])", NL(100, 999, 3, 10), edges=["3\n1 2 3\n"])
py(D, "Reverse in Place Ledger", "An accountant reverses a ledger of `n` entries by swapping from both ends (no slicing). Print the reversed entries.", IN, "The reversed list.", "1 <= n <= 100",
   "n = int(input())\na = input().split()\ni, j = 0, n - 1\nwhile i < j:\n    a[i], a[j] = a[j], a[i]\n    i += 1\n    j -= 1\nprint(*a)", NL(1, 99), edges=["1\n5\n"])
py(D, "Rank the Marks", "Given `n` marks, print each mark's rank (1 for the highest). Equal marks share the same rank (the first rank they would take).", IN, "The rank of each mark in input order.", "1 <= n <= 100",
   "n = int(input())\nm = list(map(int, input().split()))\ns = sorted(m, reverse=True)\nprint(*(s.index(v) + 1 for v in m))", NL(30, 100), edges=["3\n80 80 70\n"])
py(D, "Pairs That Sum to Target", "A cashier needs two different coins that add to `t`. Print the 0-based indices `i j` (i < j) of the first such pair in index order, or `None`.", "First line `n t`, then `n` coin values.", "`i j` or `None`.", "2 <= n <= 100",
   "n, t = map(int, input().split())\nc = list(map(int, input().split()))\nfor i in range(n):\n    for j in range(i + 1, n):\n        if c[i] + c[j] == t:\n            print(i, j)\n            raise SystemExit\nprint(\"None\")", lambda r: (lambda k: rows(f"{k} {r.randint(5, 25)}", " ".join(str(r.randint(1, 15)) for _ in range(k))))(r.randint(3, 9)), edges=["2 10\n5 5\n"])
py(D, "Missing Ticket Number", "Tickets are numbered 1 to `n+1` but one number is missing from the list of `n` numbers. Print the missing number.", IN, "The missing number.", "1 <= n <= 1000",
   "n = int(input())\nprint((n + 1) * (n + 2) // 2 - sum(map(int, input().split())))", lambda r: (lambda n: (lambda full: (lambda miss: rows(n, " ".join(str(x) for x in r.sample([x for x in full if x != miss], n))))(r.choice(full)))(list(range(1, n + 2))))(r.randint(3, 10)), edges=["1\n2\n", "1\n1\n"])
py(D, "Frequency of Each Mark", "A teacher counts how many students got each distinct mark. Print `mark count` lines sorted by mark.", IN, "Lines `mark count`.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nfor m in sorted(set(v)):\n    print(m, v.count(m))", NL(1, 6, 4, 14), edges=["1\n3\n"])
py(D, "Sum of Each Diagonal", "A game board stores an `n` by `n` grid of points. Print the sum of the main diagonal and the anti-diagonal.", "First line `n`, then `n` lines of `n` integers.", "`main anti`.", "1 <= n <= 10",
   "n = int(input())\ng = [list(map(int, input().split())) for _ in range(n)]\nprint(sum(g[i][i] for i in range(n)), sum(g[i][n - 1 - i] for i in range(n)))", lambda r: (lambda n: rows(n, *[" ".join(str(r.randint(1, 20)) for _ in range(n)) for _ in range(n)]))(r.randint(1, 5)), edges=["1\n7\n"])
py(D, "Move Zeros to End", "A data feed has missing readings as 0. Move all zeros to the end while keeping the other readings in order, and print the list.", IN, "The rearranged list.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nprint(*([x for x in v if x] + [x for x in v if not x]))", NL(0, 5, 4, 12), edges=["1\n0\n"])
py(D, "Longest Increasing Stretch", "A stock chart has `n` daily prices. Print the length of the longest run of strictly increasing consecutive prices.", IN, "The run length.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nbest = cur = 1\nfor i in range(1, n):\n    cur = cur + 1 if v[i] > v[i - 1] else 1\n    best = max(best, cur)\nprint(best)", NL(1, 30, 3, 14), edges=["1\n5\n", "3\n5 5 5\n"])
py(D, "Split Even and Odd Parcels", "Parcel weights are split into even and odd weights. Print the even ones on the first line and the odd ones on the second line (keep their order; print an empty line if none).", IN, "Two lines.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nprint(*[x for x in v if x % 2 == 0])\nprint(*[x for x in v if x % 2])", NL(1, 40), edges=["1\n2\n"])
py(D, "Nested Class Totals", "A school stores marks as a list of lists, one list per class. Print the total of every class, then the grand total, all on one line.", "First line `c`, then `c` lines; each line starts with the count `k` then `k` marks.", "The class totals and the grand total.", "1 <= c <= 10",
   "c = int(input())\ntotals = []\nfor _ in range(c):\n    row = list(map(int, input().split()))[1:]\n    totals.append(sum(row))\nprint(*totals, sum(totals))", lambda r: (lambda c: rows(c, *[" ".join(map(str, [k] + [r.randint(30, 100) for _ in range(k)])) for k in [r.randint(1, 5) for _ in range(c)]]))(r.randint(1, 4)), edges=["1\n1 50\n"])
py(D, "Chunk the Orders", "A packer puts orders into boxes of size `k`. Print each box (a chunk of `k` consecutive orders, the last may be shorter) on its own line.", "First line `n k`, then `n` order ids.", "One line per box.", "1 <= n <= 100, 1 <= k <= 100",
   "n, k = map(int, input().split())\no = input().split()\nfor i in range(0, n, k):\n    print(*o[i:i + k])", lambda r: (lambda n: rows(f"{n} {r.randint(1, 5)}", " ".join(str(r.randint(100, 999)) for _ in range(n))))(r.randint(1, 11)), edges=["1 1\n5\n"])
py(D, "Sort by Last Digit", "A lottery sorts tickets by their last digit, and by value when last digits tie. Print the sorted tickets.", IN, "The sorted tickets.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nprint(*sorted(v, key=lambda x: (x % 10, x)))", NL(10, 999), edges=["1\n5\n"])
py(D, "Balanced Scale Split", "A jeweller has `n` stones and wants to know if the list can be split at some position into a left part and a right part with equal sums (both parts non-empty). Print `Yes` or `No`.", IN, "`Yes` or `No`.", "2 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\ntotal = sum(v)\nleft = 0\nfor i in range(n - 1):\n    left += v[i]\n    if left * 2 == total:\n        print(\"Yes\")\n        break\nelse:\n    print(\"No\")", NL(1, 6, 2, 8), edges=["2\n3 3\n", "2\n1 2\n"])
py(D, "Intersection of Two Playlists", "Two friends list song ids. Print the ids that appear in both lists, once each, in the order they appear in the first list.", "Line 1: `n` and the `n` ids; line 2: `m` and the `m` ids.", "The common ids or `None`.", "1 <= n, m <= 50",
   "a = input().split()[1:]\nb = set(input().split()[1:])\nres = []\nfor x in a:\n    if x in b and x not in res:\n        res.append(x)\nprint(*res if res else [\"None\"])", lambda r: (lambda a, b: rows(" ".join(map(str, [len(a)] + a)), " ".join(map(str, [len(b)] + b))))([r.randint(1, 12) for _ in range(r.randint(2, 7))], [r.randint(1, 12) for _ in range(r.randint(2, 7))]), edges=["1 1\n1 2\n"])
py(D, "Median Delivery Time", "A courier company lists `n` delivery times. Print the median (the middle value for odd `n`, the average of the two middle values for even `n`) with one decimal.", IN, "The median, one decimal.", "1 <= n <= 100",
   "n = int(input())\nv = sorted(map(int, input().split()))\nm = n // 2\nprint(f\"{v[m] if n % 2 else (v[m - 1] + v[m]) / 2:.1f}\")", NL(5, 90, 1, 10), edges=["1\n7\n", "2\n1 2\n"])

py(D, "Peak Hour Traffic", "A road sensor counts cars each hour for `n` hours. Print the 1-based hours (in order) when the count was at its maximum.", IN, "The hours separated by spaces.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\ntop = max(v)\nprint(*[i + 1 for i, x in enumerate(v) if x == top])", NL(1, 20, 3, 12), edges=["1\n7\n", "3\n5 5 5\n"])

# ---- 15 tuples ----
py(D, "Coordinates Distance", "A delivery map stores two points as tuples `(x, y)`. Print the Euclidean distance between them with two decimals.", "One line `x1 y1 x2 y2`.", "The distance, two decimals.", "-1000 <= coordinates <= 1000",
   "import math\nx1, y1, x2, y2 = map(int, input().split())\np, q = (x1, y1), (x2, y2)\nprint(f\"{math.dist(p, q):.2f}\")", lambda r: one_line(*[r.randint(-50, 50) for _ in range(4)]), edges=["0 0 0 0\n", "0 0 3 4\n"])
py(D, "Swap Pair of Seats", "A seat map stores a pair `(row, seat)`. Print the pair swapped as `seat row` using tuple unpacking.", "One line `row seat`.", "`seat row`.", "Both are integers.",
   "row, seat = map(int, input().split())\np = (row, seat)\np = p[::-1]\nprint(*p)", lambda r: one_line(r.randint(1, 40), r.randint(1, 30)))
py(D, "Min and Max as a Tuple", "A function returns the lowest and highest temperature of the day as a tuple. Given `n` readings print `low high`.", IN, "`low high`.", "1 <= n <= 100",
   "n = int(input())\nv = list(map(int, input().split()))\nresult = (min(v), max(v))\nprint(*result)", NL(-10, 45), edges=["1\n5\n"])
py(D, "Student Records Sorted", "Each student is stored as a tuple `(name, marks)`. Read `n` records and print the names sorted by marks, highest first, and by name when marks tie.", "First line `n`, then `n` lines `name marks`.", "The sorted names, one per line.", "1 <= n <= 30",
   "n = int(input())\nrec = []\nfor _ in range(n):\n    name, m = input().split()\n    rec.append((name, int(m)))\nrec.sort(key=lambda t: (-t[1], t[0]))\nfor name, _ in rec:\n    print(name)", lambda r: (lambda n: rows(n, *[f"{nm} {r.randint(40, 100)}" for nm in r.sample(['Asha', 'Ravi', 'Meena', 'Kiran', 'Sita', 'Arun', 'Divya'], n)]))(r.randint(2, 6)), edges=["1\nAsha 50\n"])
py(D, "Tuple Immutability Check", "Weekday names are stored either as a list or as a tuple. Given the kind, a 0-based index `i` and a new name, try to assign the new name at that index. Print `Changed` if it worked or `Tuples are immutable` if Python refuses.", "One line `kind i name` where `kind` is `list` or `tuple`.", "`Changed` or the message.", "0 <= i <= 6",
   "kind, i, name = input().split()\ndays = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]\nif kind == \"tuple\":\n    days = tuple(days)\ntry:\n    days[int(i)] = name\n    print(\"Changed\")\nexcept TypeError:\n    print(\"Tuples are immutable\")", lambda r: one_line(r.choice(["list", "tuple"]), r.randint(0, 6), r.choice(["Mon", "Holiday", "X"])), edges=["list 0 Z\n", "tuple 0 Z\n"])
py(D, "Count Item in Tuple", "An inventory tuple holds item codes. Print how many times the code `x` appears.", "First line `n x`, then `n` codes.", "The count.", "1 <= n <= 100",
   "n, x = input().split()\nitems = tuple(input().split())\nprint(items.count(x))", lambda r: (lambda k: rows(f"{k} {r.randint(1, 5)}", " ".join(str(r.randint(1, 5)) for _ in range(k))))(r.randint(2, 10)), edges=["1 9\n1\n"])
py(D, "Nested Tuple Totals", "A bill is a tuple of `(item, price, qty)` tuples. Read `n` lines `item price qty` and print the grand total.", "First line `n`, then `n` lines `item price qty`.", "The total.", "1 <= n <= 30",
   "n = int(input())\nbill = tuple(tuple(input().split()) for _ in range(n))\nprint(sum(int(p) * int(q) for _, p, q in bill))", lambda r: (lambda n: rows(n, *[f"{r.choice(['pen', 'ink', 'book', 'bag'])} {r.randint(5, 500)} {r.randint(1, 9)}" for _ in range(n)]))(r.randint(1, 6)), edges=["1\npen 10 1\n"])
py(D, "Pack and Unpack", "A date is read as `day month year` and packed into a tuple. Print it in the format `year-month-day`, with month and day padded to two digits.", "One line `day month year`.", "`YYYY-MM-DD`.", "Valid date.",
   "d, m, y = map(int, input().split())\ndate = (d, m, y)\nday, month, year = date\nprint(f\"{year}-{month:02d}-{day:02d}\")", lambda r: one_line(r.randint(1, 28), r.randint(1, 12), r.randint(1990, 2030)))
py(D, "Closest Pair of Points", "A drone sees `n` points as `(x, y)` tuples. Print the squared distance of the closest pair of different points.", "First line `n`, then `n` lines `x y`.", "The smallest squared distance.", "2 <= n <= 30",
   "n = int(input())\npts = [tuple(map(int, input().split())) for _ in range(n)]\nbest = None\nfor i in range(n):\n    for j in range(i + 1, n):\n        d = (pts[i][0] - pts[j][0]) ** 2 + (pts[i][1] - pts[j][1]) ** 2\n        if best is None or d < best:\n            best = d\nprint(best)", lambda r: (lambda n: rows(n, *[one_line(r.randint(-20, 20), r.randint(-20, 20)).strip() for _ in range(n)]))(r.randint(2, 6)), edges=["2\n0 0\n0 0\n"])
py(D, "Tuple Concatenation Log", "Two shifts record log codes as tuples. Print the combined tuple of shift 1 followed by shift 2 and its length.", "Line 1: shift 1 codes; line 2: shift 2 codes.", "The combined codes and the length on the next line.", "Each line has at least one code.",
   "a = tuple(input().split())\nb = tuple(input().split())\nc = a + b\nprint(*c)\nprint(len(c))", lambda r: rows(" ".join(str(r.randint(1, 99)) for _ in range(r.randint(1, 5))), " ".join(str(r.randint(1, 99)) for _ in range(r.randint(1, 5)))), edges=["1\n2\n"])
py(D, "Tuple as Dictionary Key Grid", "A seat is a tuple `(row, col)`. Read `n` booked seats and then a query seat. Print `Booked` if the query is among them, else `Free`.", "First line `n`, then `n` lines `row col`, then the query line `row col`.", "`Booked` or `Free`.", "1 <= n <= 30",
   "n = int(input())\nbooked = {tuple(map(int, input().split())) for _ in range(n)}\nq = tuple(map(int, input().split()))\nprint(\"Booked\" if q in booked else \"Free\")", lambda r: (lambda n: rows(n, *[one_line(r.randint(1, 4), r.randint(1, 4)).strip() for _ in range(n)], one_line(r.randint(1, 4), r.randint(1, 4)).strip()))(r.randint(1, 8)), edges=["1\n1 1\n1 1\n"])
py(D, "Rectangle Corner Tuple", "A rectangle is stored as `(x1, y1, x2, y2)` for its opposite corners (any order). Print its area and perimeter.", "One line `x1 y1 x2 y2`.", "`area perimeter`.", "-1000 <= coordinates <= 1000",
   "x1, y1, x2, y2 = map(int, input().split())\nw, h = abs(x2 - x1), abs(y2 - y1)\nprint(w * h, 2 * (w + h))", lambda r: one_line(*[r.randint(-30, 30) for _ in range(4)]), edges=["0 0 0 0\n", "3 3 0 0\n"])
py(D, "Pair Up Names and Marks", "Two lines hold `n` names and `n` marks. Zip them into tuples and print the pairs `name:mark` separated by spaces.", "First line `n`, then names, then marks.", "The pairs.", "1 <= n <= 30",
   "n = int(input())\nnames = input().split()\nmarks = input().split()\nprint(*(f\"{a}:{b}\" for a, b in zip(names, marks)))", lambda r: (lambda n: rows(n, " ".join(r.sample(['Asha', 'Ravi', 'Meena', 'Kiran', 'Sita', 'Arun', 'Divya'], n)), " ".join(str(r.randint(30, 99)) for _ in range(n))))(r.randint(1, 6)), edges=["1\nA\n5\n"])
py(D, "Highest Scorer Tuple", "Players are tuples `(name, score)`. Print the name and score of the highest scorer (the first one if tied).", "First line `n`, then `n` lines `name score`.", "`name score`.", "1 <= n <= 30",
   "n = int(input())\nbest = None\nfor _ in range(n):\n    name, s = input().split()\n    t = (name, int(s))\n    if best is None or t[1] > best[1]:\n        best = t\nprint(*best)", lambda r: (lambda n: rows(n, *[f"{nm} {r.randint(1, 100)}" for nm in r.sample(['Asha', 'Ravi', 'Meena', 'Kiran', 'Sita', 'Arun'], n)]))(r.randint(1, 6)), edges=["2\nA 5\nB 5\n"])
py(D, "Tuple Slicing Timetable", "A timetable tuple holds `n` period names. Print the first two periods, the last two periods and every other period starting from the first, on three lines.", "First line `n`, then `n` period names.", "Three lines.", "4 <= n <= 20",
   "n = int(input())\nt = tuple(input().split())\nprint(*t[:2])\nprint(*t[-2:])\nprint(*t[::2])", lambda r: (lambda n: rows(n, " ".join(r.sample(['Math', 'Phy', 'Chem', 'Bio', 'Eng', 'Hist', 'Geo', 'Art', 'Music', 'PE'], n))))(r.randint(4, 9)), edges=["4\nA B C D\n"])

